import 'package:flutter/cupertino.dart';
import '../../core/business_api_client.dart';
final class RedPacketPage extends StatefulWidget { const RedPacketPage({super.key, this.api}); final BusinessApiClient? api; @override State<RedPacketPage> createState()=>_RedPacketPageState(); }
final class _RedPacketPageState extends State<RedPacketPage> { String mode='EQUAL'; final total=TextEditingController(); final shares=TextEditingController(text:'1'); String? result; @override void dispose(){total.dispose(); shares.dispose(); super.dispose();} Future<void> create() async { try { final r=await widget.api?.createRedPacket(mode: mode,total: total.text.trim(),shareCount:int.tryParse(shares.text)??1); setState(()=>result='红包已创建：${r?['id']??'处理中'}'); } catch(e){setState(()=>result=e.toString());} } @override Widget build(BuildContext context)=>ListView(padding: const EdgeInsets.all(20),children:[const Text('彩币红包',style:TextStyle(fontSize:32,fontWeight:FontWeight.w700)),const SizedBox(height:18),CupertinoSlidingSegmentedControl<String>(groupValue:mode,children:const {'EQUAL':Text('等额'),'LUCKY':Text('拼手气')},onValueChanged:(v)=>setState(()=>mode=v!)),CupertinoListSection.insetGrouped(header:const Text('创建红包'),children:[CupertinoTextField(controller:total,placeholder:'总金额',keyboardType:TextInputType.number,padding:const EdgeInsets.all(14)),CupertinoTextField(controller:shares,placeholder:'份数',keyboardType:TextInputType.number,padding:const EdgeInsets.all(14)),CupertinoButton.filled(onPressed:widget.api==null?null:create,child:const Text('发红包'))]),if(result!=null)Text(result!),const Text('红包有效期 24 小时，未领取金额自动退回')]); }
